from decimal import Decimal

import pytest
from django.core.files.uploadedfile import SimpleUploadedFile

from apps.accounts.tests.factories import StudentFactory
from apps.assessments.models import FinalReport
from apps.assessments.services import (
    AssessmentService,
    FinalReportService,
    ResultService,
)
from apps.assessments.tests.factories import full_scores, make_forms
from apps.core.exceptions import InvalidTransition, NotAllowed, RuleViolation
from apps.placements.tests.factories import ApprovedPlacementFactory, SubmittedPlacementFactory

pytestmark = pytest.mark.django_db

PDF = b"%PDF-1.4\n" + b"0" * 128


def _pdf(name="report.pdf", content=PDF):
    return SimpleUploadedFile(name, content, content_type="application/pdf")


def _submit_assessment(actor, placement, form, ratio=1.0):
    assessment = AssessmentService.create_draft(
        actor=actor, placement=placement, form=form, scores=full_scores(form, ratio)
    )
    return AssessmentService.submit(actor=actor, assessment=assessment)


@pytest.fixture
def setup():
    placement = ApprovedPlacementFactory()
    workplace, academic = make_forms(placement.period)
    return placement, workplace, academic


# ------------------------------------------------------------ assessments -------------
def test_assessor_must_be_the_assigned_supervisor_with_the_matching_role(setup, student):
    placement, workplace, academic = setup
    with pytest.raises(NotAllowed):  # student
        AssessmentService.create_draft(actor=student, placement=placement, form=workplace)
    with pytest.raises(NotAllowed):  # academic supervisor on the workplace form
        AssessmentService.create_draft(
            actor=placement.academic_supervisor, placement=placement, form=workplace
        )
    other = ApprovedPlacementFactory(period=placement.period)
    with pytest.raises(NotAllowed):  # a different placement's workplace supervisor
        AssessmentService.create_draft(
            actor=other.workplace_supervisor, placement=placement, form=workplace
        )


def test_assessment_window_must_be_open(setup):
    from datetime import timedelta

    from django.utils import timezone

    placement, workplace, _ = setup
    placement.period.assessment_opens_on = timezone.localdate() + timedelta(days=5)
    placement.period.save()
    with pytest.raises(RuleViolation) as error:
        AssessmentService.create_draft(
            actor=placement.workplace_supervisor, placement=placement, form=workplace
        )
    assert error.value.code == "assessment_not_open"


def test_scores_are_validated(setup):
    placement, workplace, _ = setup
    actor = placement.workplace_supervisor
    criterion = workplace.criteria.filter(type="SCORE").first()
    comment_criterion = workplace.criteria.filter(type="COMMENT").first()
    with pytest.raises(RuleViolation) as error:
        AssessmentService.create_draft(
            actor=actor,
            placement=placement,
            form=workplace,
            scores=[{"criterion": criterion.id, "score": criterion.max_score + 1}],
        )
    assert error.value.code == "score_out_of_range"
    with pytest.raises(RuleViolation):
        AssessmentService.create_draft(
            actor=actor,
            placement=placement,
            form=workplace,
            scores=[{"criterion": comment_criterion.id, "score": 3}],
        )


def test_cannot_submit_until_required_criteria_are_scored(setup):
    placement, workplace, _ = setup
    actor = placement.workplace_supervisor
    first = workplace.criteria.filter(type="SCORE").first()
    assessment = AssessmentService.create_draft(
        actor=actor,
        placement=placement,
        form=workplace,
        scores=[{"criterion": first.id, "score": 5}],
    )
    with pytest.raises(RuleViolation) as error:
        AssessmentService.submit(actor=actor, assessment=assessment)
    assert error.value.code == "incomplete_assessment"
    assert "W02" in error.value.details["missing"]
    assert "W06" not in error.value.details["missing"]  # optional criterion


def test_submit_computes_the_percent_and_locks(setup):
    placement, workplace, _ = setup
    actor = placement.workplace_supervisor
    assessment = _submit_assessment(actor, placement, workplace, ratio=1.0)
    assert assessment.percent == Decimal("100.00")
    assert assessment.status == "SUBMITTED"
    with pytest.raises(InvalidTransition):
        AssessmentService.update_draft(actor=actor, assessment=assessment, comment="Late edit")
    with pytest.raises(InvalidTransition):
        AssessmentService.submit(actor=actor, assessment=assessment)


def test_one_assessment_per_form(setup):
    placement, workplace, _ = setup
    actor = placement.workplace_supervisor
    AssessmentService.create_draft(actor=actor, placement=placement, form=workplace)
    with pytest.raises(InvalidTransition) as error:
        AssessmentService.create_draft(actor=actor, placement=placement, form=workplace)
    assert error.value.code == "assessment_exists"


# ------------------------------------------------------------ final report ------------
def test_student_uploads_and_replaces_until_accepted(setup):
    placement, _, _ = setup
    report = FinalReportService.upload(
        actor=placement.student, placement=placement, file=_pdf(), title="My report"
    )
    assert report.status == "SUBMITTED"
    assert report.original_name == "report.pdf"
    assert report.document.name.endswith(".pdf")
    replaced = FinalReportService.upload(
        actor=placement.student, placement=placement, file=_pdf("v2.pdf")
    )
    assert replaced.pk == report.pk
    assert replaced.original_name == "v2.pdf"


def test_upload_validation_and_ownership(setup):
    placement, _, _ = setup
    with pytest.raises(RuleViolation) as error:
        FinalReportService.upload(
            actor=placement.student, placement=placement, file=_pdf("evil.pdf", b"MZ" + b"0" * 64)
        )
    assert error.value.code == "bad_content"
    with pytest.raises(NotAllowed):
        FinalReportService.upload(actor=StudentFactory(), placement=placement, file=_pdf())
    submitted = SubmittedPlacementFactory()
    with pytest.raises(InvalidTransition):
        FinalReportService.upload(actor=submitted.student, placement=submitted, file=_pdf())


def test_academic_supervisor_reviews_the_report(setup):
    placement, _, _ = setup
    report = FinalReportService.upload(actor=placement.student, placement=placement, file=_pdf())
    with pytest.raises(NotAllowed):
        FinalReportService.accept(actor=placement.workplace_supervisor, report=report)
    with pytest.raises(RuleViolation):
        FinalReportService.return_report(
            actor=placement.academic_supervisor, report=report, feedback=" "
        )
    FinalReportService.return_report(
        actor=placement.academic_supervisor, report=report, feedback="Add a conclusion."
    )
    assert report.status == "RETURNED"
    FinalReportService.upload(actor=placement.student, placement=placement, file=_pdf("v2.pdf"))
    report.refresh_from_db()
    FinalReportService.accept(actor=placement.academic_supervisor, report=report)
    assert report.status == FinalReport.Status.ACCEPTED
    with pytest.raises(InvalidTransition) as error:
        FinalReportService.upload(actor=placement.student, placement=placement, file=_pdf("v3.pdf"))
    assert error.value.code == "report_locked"


