def test_preview_lists_what_is_missing(setup):
    placement, workplace, academic = setup
    preview = ResultService.preview(placement)
    assert not preview["ready"]
    assert preview["total_percent"] is None
    assert len(preview["missing"]) == 3  # two forms and the report

    _submit_assessment(placement.workplace_supervisor, placement, workplace)
    assert len(ResultService.preview(placement)["missing"]) == 2


def test_finalize_needs_everything_then_writes_a_snapshot(setup, coordinator):
    placement, workplace, academic = setup
    with pytest.raises(RuleViolation) as error:
        ResultService.finalize(actor=coordinator, placement=placement)
    assert error.value.code == "not_ready"

    _submit_assessment(placement.workplace_supervisor, placement, workplace, ratio=1.0)  # 100%
    _submit_assessment(placement.academic_supervisor, placement, academic, ratio=0.5)  # 50%
    report = FinalReportService.upload(actor=placement.student, placement=placement, file=_pdf())
    FinalReportService.accept(actor=placement.academic_supervisor, report=report)

    preview = ResultService.preview(placement)
    assert preview["ready"]
    assert preview["total_percent"] == Decimal("80.00")  # 100*0.6 + 50*0.4
    assert preview["grade"] == "A"

    result = ResultService.finalize(actor=coordinator, placement=placement)
    assert result.total_percent == Decimal("80.00")
    assert result.grade == "A"
    assert len(result.breakdown) == 2
    assert ResultService.preview(placement)["finalized"] is True
    with pytest.raises(InvalidTransition) as again:
        ResultService.finalize(actor=coordinator, placement=placement)
    assert again.value.code == "already_finalized"


def test_only_coordinators_finalize(setup):
    placement, _, _ = setup
    with pytest.raises(NotAllowed):
        ResultService.finalize(actor=placement.academic_supervisor, placement=placement)


def test_report_requirement_can_be_switched_off(setup, coordinator, settings):
    settings.REQUIRE_FINAL_REPORT_FOR_RESULT = False
    placement, workplace, academic = setup
    _submit_assessment(placement.workplace_supervisor, placement, workplace)
    _submit_assessment(placement.academic_supervisor, placement, academic)
    assert ResultService.preview(placement)["ready"]


def test_form_weights_must_add_up_to_100(setup, settings):
    from apps.assessments.services import AssessmentFormService

    settings.REQUIRE_FINAL_REPORT_FOR_RESULT = False
    placement, workplace, academic = setup
    AssessmentFormService.patch(form=academic, weight_percent=10)
    _submit_assessment(placement.workplace_supervisor, placement, workplace)
    _submit_assessment(placement.academic_supervisor, placement, academic)
    preview = ResultService.preview(placement)
    assert not preview["ready"]
    assert any("add up to 100" in message for message in preview["missing"])
